using System;using System.Collections.Generic;using System.Drawing;using System.IO;using System.Linq;using System.Reflection;using System.Windows.Forms;using MP1SkinStudio.Live;using MP1SkinStudio.LiveBridge;using MediaPortal.GUI.Library;
class NativeProbe{
 static List<string> results=new List<string>();static void Check(bool c,string name){if(!c)throw new Exception(name);results.Add("PASS "+name);}static void Reject(System.Action a,string name){bool rejected=false;try{a();}catch{rejected=true;}Check(rejected,name);}
 static GUIFont Fake(LiveFontDefinition d,string n,int p){return new GUIFont{FontName=n,FileName=d.Family,FontSize=p,FontStyle=(FontStyle)d.Style,ID=-1};}
 [STAThread]static int Main(string[] args){var registry=typeof(GUIFontManager).GetField("ListFonts",BindingFlags.Static|BindingFlags.NonPublic);var originalRegistry=registry.GetValue(null);var creator=typeof(RuntimeFonts).GetField("create",BindingFlags.Static|BindingFlags.NonPublic);var originalCreator=creator.GetValue(null);var pool=typeof(RuntimeFonts).GetField("cache",BindingFlags.Static|BindingFlags.NonPublic);try{Directory.CreateDirectory(args[0]);GUIGraphicsContext.form=new Form{ClientSize=new Size(1920,1080)};GUIGraphicsContext.form.CreateControl();GUIGraphicsContext.Skin="C:\\Skin";GUIGraphicsContext.SkinSize=new Size(1920,1080);GUIGraphicsContext.OverScanWidth=1920;GUIGraphicsContext.OverScanHeight=1080;var original=new GUIFont{FontName="Original",FileName="Arial",FontSize=12,ID=0};var fonts=new List<GUIFont>{original};registry.SetValue(null,fonts);creator.SetValue(null,new Func<LiveFontDefinition,string,int,GUIFont>(Fake));
 var definition=new LiveFontDefinition{Family="Arial",Height=18,Style=0};string stamp=RuntimeFonts.RegistryStamp;string wire=definition.ToWire(),name=RuntimeFonts.Resolve(wire);Check(RuntimeFonts.RegistryStamp==stamp,"private allocation preserves the original font registry identity");Check(fonts.Count==2&&Object.ReferenceEquals(fonts[0],original),"private preview appends a font without replacing original registry entries");Check(name.StartsWith("mp1studiofont_")&&fonts[1].ID>original.ID,"private preview has its own alias and ID");Check(RuntimeFonts.Resolve(wire)==name&&fonts.Count==2,"identical definitions reuse a bounded cache entry");definition.Style=1;string bold=RuntimeFonts.Resolve(definition.ToWire());Check(bold!=name,"style changes have distinct font cache identities");definition.Family="Segoe UI";Check(RuntimeFonts.Resolve(definition.ToWire())!=bold,"family changes have distinct cache identities");
 var label=new GUILabelControl(0);label.FontName="Original";var slot=RuntimeProperty.For(label,"C:\\Skin")["font"];var saved=slot.Read();slot.Write(slot.Parse(wire));Check(label.FontName==name,"native font property accepts a private definition descriptor");slot.Write(saved);Check(label.FontName=="Original"&&Object.ReferenceEquals(GUIFontManager.GetFont("Original"),original),"font restoration retains the original registered object");
 Reject(()=>RuntimeFonts.Resolve(LiveFontDefinition.Prefix+"bad-base64"),"malformed font descriptor is rejected");Reject(()=>RuntimeFonts.Resolve(new LiveFontDefinition{Family="../Arial",Height=18}.ToWire()),"font paths are rejected before allocation");Check(fonts[0].FontSize==12&&fonts[0].FileName=="Arial","preview variants never mutate the original font definition");
 for(int i=1;i<=35;i++){try{RuntimeFonts.Resolve(new LiveFontDefinition{Family="Arial",Height=i,Style=2}.ToWire());}catch(InvalidOperationException){break;}}Check(((Dictionary<string,GUIFont>)pool.GetValue(null)).Count==32,"private font variants are limited to 32 per active registry");int count=fonts.Count;Reject(()=>RuntimeFonts.Resolve(new LiveFontDefinition{Family="Arial",Height=95,Style=3}.ToWire()),"a full preview cache rejects another allocation");Check(fonts.Count==count&&Object.ReferenceEquals(fonts[0],original),"capacity rejection preserves the registry and original font");
 registry.SetValue(null,new List<GUIFont>{original});Check(RuntimeFonts.Resolve(wire).StartsWith("mp1studiofont_")&&((Dictionary<string,GUIFont>)pool.GetValue(null)).Count==1,"normal MP registry replacement invalidates obsolete private cache entries");label.FontName="Original";label.GetID=77;label.Type="label";var window=new GUIWindow();typeof(GUIWindow).GetField("_windowLoaded",BindingFlags.Instance|BindingFlags.NonPublic).SetValue(window,true);typeof(GUIWindow).GetField("_windowXmlFileName",BindingFlags.Instance|BindingFlags.NonPublic).SetValue(window,"C:\\Skin\\font.xml");window.Children.Add(label);var session=new RuntimeSession(()=>window);var first=session.Handle(LiveWire.Document("snapshot"));var replacement=new GUIFont{FontName="Original",FileName="Arial",FontSize=12,ID=0};registry.SetValue(null,new List<GUIFont>{replacement});Check(session.Handle(LiveWire.Document("ping")).DocumentElement.GetAttribute("current")=="false","normal registry replacement invalidates the live window context");Check(session.Handle(LiveWire.Document("snapshot")).DocumentElement.GetAttribute("epoch")!=first.DocumentElement.GetAttribute("epoch"),"font registry replacement starts a fresh runtime epoch");session.Reset();Console.WriteLine(results.Count+" native font checks passed.");return 0;
 }catch(Exception ex){results.Add(ex.ToString());return 1;}finally{registry.SetValue(null,originalRegistry);creator.SetValue(null,originalCreator);((Dictionary<string,GUIFont>)pool.GetValue(null)).Clear();Directory.CreateDirectory(args[0]);File.WriteAllLines(Path.Combine(args[0],"Results.txt"),results);foreach(string r in results)Console.WriteLine(r);if(GUIGraphicsContext.form!=null)GUIGraphicsContext.form.Dispose();}}
}
